    // --- State Variables ─────────────────────────────────────

    address constant TARGET = 0x8fAc119886DD328a84Cd545881C7A484017E7Ce6;
    address attacker = address(this);
    address owner;
    address victim = makeAddr("victim");

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {

        // Cast TARGET to the contract interface
                memefarm target = memefarm(TARGET);

                // Identify the owner
